import sys, numpy as np
from rdkit import Chem
f=sys.argv[1]
L=open(f).read().split('\n')[2:]
c={i:np.array(list(map(float,l.split()[1:]))) for i,l in enumerate(L) if l.strip()}
mh=Chem.MolFromMolFile('ref.mol', removeHs=False, sanitize=False)
ref={tuple(sorted((b.GetBeginAtomIdx(),b.GetEndAtomIdx()))) for b in mh.GetBonds()}
sym=[a.GetSymbol() for a in mh.GetAtoms()]
cov={'C':0.76,'H':0.31,'N':0.71,'P':1.07,'Cl':1.02,'Ni':1.24}
n=len(sym); got=set()
for i in range(n):
    for j in range(i+1,n):
        if np.linalg.norm(c[i]-c[j]) < 1.2*(cov[sym[i]]+cov[sym[j]]): got.add((i,j))
print("missing:",ref-got); print("extra:",got-ref)
def ang(a,b,c_):
    v1=c[a]-c[b]; v2=c[c_]-c[b]; return np.degrees(np.arccos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
print('P-Ni-P %.1f N-Ni-C %.1f'%(ang(28,27,47),ang(26,27,66)))
for i in [26,28,47,66]: print(' Ni-%s%d %.3f'%(sym[i],i,np.linalg.norm(c[i]-c[27])))
hmin=min((np.linalg.norm(c[i]-c[27]),i) for i in range(n) if sym[i]=='H'); print("closest H to Ni:",hmin)
